mapper.select:
SELECT distinct A.BOOKSET_SCHEME_ID id, B.SCH_NAME text FROM BOK_BOOKSET_PLAN A INNER JOIN BOK_SCHEME_INFO B ON B.SCH_ID = A.SCHEME_ID INNER JOIN BOK_BOOKSET D ON D.BOOKSET_ID = A.BOOKSET_ID WHERE 1=1
AND D.BOOKSET_TYPE = #{booksetType}
AND D.BOOKSET_ID = #{booksetId}
AND B.SCHEME_TYPE IN
#{item}
AND B.SCH_NAME like concat_ws('','%' , #{likeStr} , '%') OR A.BOOKSET_SCHEME_ID like concat_ws('','%' , #{likeStr} , '%')
order by A.BOOKSET_SCHEME_ID desc

SELECT distinct A.BOOKSET_SCHEME_ID booksetSchemeId, A.SCHEME_ID as schId, A.BOOKSET_ID as booksetId, B.SCH_NAME schName, B.SCHEME_TYPE schemeType, B.IS_DEFAULT isDefault, C.BOOKSET_NAME booksetName, D.ERROR_NUMBER errorNumber, D.MY_START_ROW_NO myStartRowNo, D.OTHERSIDE_START_ROW_NO othersideStartRowNo FROM BOK_BOOKSET_PLAN A INNER JOIN BOK_SCHEME_INFO B ON B.SCH_ID = A.SCHEME_ID INNER JOIN BOK_BOOKSET C ON C.BOOKSET_ID = A.BOOKSET_ID LEFT JOIN BOK_SCHEME_INFO_DETAIL D ON D.SCH_ID = A.SCHEME_ID WHERE 1=1
AND C.BOOKSET_TYPE = #{booksetType}
AND C.BOOKSET_ID = #{booksetId}
AND B.SCHEME_TYPE IN
#{item}
AND B.SCH_NAME like concat_ws('','%' , #{searchKey} , '%')
